import{t as e}from"./utils-COoNfFoj.js";var t={slug:`colin-rocker`,influencerName:`Colin Rocker`,influencerHandle:`@careercolin`,influencerAvatarUrl:`${e}/colin-rocker-avatar.png`,heroDescription:`Making my first investment took a ton of research, and now I’m hooked. I used Perplexity Computer to build a deal flow dashboard to help source my next investment, and I’m sharing it with you. Try my prompt below, or create your own!`,assetTitle:`Deal Flow Terminal`,screenshotUrl:`${e}/colin-rocker.png`,remixUrl:`https://www.perplexity.ai/computer/a/first-gen-deal-flow-terminal-xdbjv2hyTXm0H8k3l61yaw`,promptTitle:`Try Colin's Prompt`,promptText:`I'm a first-generation founder, content creator, and early-stage investor. Build me a founder deal flow scanner. I want it to track early-stage companies in three categories I care about most: creator economy tools, career and professional development tech, and community-building platforms. I want it to show me: recent seed and pre-seed rounds that just closed, founders getting early buzz who don't have major institutional backing yet, products that are gaining organic traction but haven't been funded yet, events happening in New York City or nearby where I could meet potential founders, chatter on social media (Twitter/X, Reddit, LinkedIn) relevant to these spaces, and “white space” — real gaps in the market where there is clear demand but no funded solution. Pull from sources like Crunchbase, Product Hunt, Twitter/X founder conversations, newsletter mentions, and any early-stage funding announcements from the last 90 days. Make it visual. I want to be able to see the landscape at a glance, not read a wall of text. Give me a dashboard I can come back to weekly. Think Bloomberg terminal meets a founder’s gut check. I didn’t grow up with investors in my network, so make sure you’re presenting this information in plain language.`};export{t as default};
